for i,(r1,c1) in enumerate(pts):
 for r2,c2 in pts[i+1:]:
  dr,dc=r2-r1,c2-c1
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   n=max(abs(dr),abs(dc))
   if n>1 and (dr==0 or dc==0 or abs(dr)==abs(dc)):
    sr=(dr>0)-(dr<0); sc=(dc>0)-(dc<0)
    if dr and dc and abs(dr)!=abs(dc): continue
    for k in range(1,n):
     r,c=r1+sr*k,c1+sc*k
     if g[r][c]==8: fills.add((r,c))
out=[row[:] for row in g]
for r,c in fills: out[r][c]=2
print(sorted(fills))
for row in out: print(row)
